import numpy as np
# cross-venue spreads
result={}
for a in ['A','B','C']:
    m1=H[a]['mid'].astype(float); m2=H[a+'.X']['mid'].astype(float)
    d=m1-m2
    m=np.nanmean(d); s=np.nanstd(d)
    def ac(x,k):
        xx=x-np.nanmean(x)
        mk=(~np.isnan(xx[:-k]))&(~np.isnan(xx[k:]))
        try:
            return float(np.corrcoef(xx[:-k][mk],xx[k:][mk])[0,1])
        except: return 0.0
    result[a]={'mean':float(m),'std':float(s),'ac10':ac(d,10),'maxabs':float(np.nanmax(np.abs(d)))}

