def signal(obs):
    out = {}
    pairs = [('A', 'A.X', 10.0), ('B', 'B.X', 8.0), ('C', 'C.X', 8.0)]
    for a, b, scale in pairs:
        try:
            m1 = obs.last(a, 'mid')
            m2 = obs.last(b, 'mid')
        except:
            continue
        if m1 != m1 or m2 != m2:
            continue
        d = m1 - m2
        if d != d:
            continue
        ad = d if d >= 0 else -d
        if ad < 4.0:
            out[a] = 0.0
            out[b] = 0.0
            continue
        s = (ad - 4.0) / scale
        if s > 1.0:
            s = 1.0
        if d < 0:
            s = -s
        out[a] = float(-s * 0.5)
        out[b] = float(s * 0.5)
    return out

