def sim_strategy(HORIZ, THR, HOLD, assets, thr_diff=None, hold_diff=25, size_idx=0.6):
    # simulate P&L on visible history mimicking engine: target [-1,1] -> lots = target*15
    # engine trades at most 2 lots per step toward target with market orders paying spread/2 + fees
    # We'll approximate: each step we try to move position toward target by at most 2 lots, cost = spread/2 per lot + fee (bps)
    # For simplicity estimate net pnl = mid delta * position - cost per trade
    # This is rough but for ranking.
    # Use mid price changes and position tracking
    n = len(H['A']['mid'])
    #init positions
    pos = {a:0.0 for a in ['A','B','C','IDX','A.X','B.X','C.X']}
    # holds
    hold = {a:0 for a in pos}
    target = {a:0.0 for a in pos}
    # state for momentum signals
    holds_mem = {}
    pos_mem = {}
    pnl=0.0
    # we need spreads for cost: use mid = (bid+ask)/2 approx, cost per lot traded = spread/2 + fee*bps*mid/10000
    # fees: A 0, A.X 0.0003, B 0, B.X 0.0003, C 0, C.X 0.0003, IDX 0? assume 0
    fee_bps = {'A':0,'A.X':3,'B':0,'B.X':3,'C':0,'C.X':3,'IDX':0}
    # track first half and second half pnl separately
    pnl_first=0
    pnl_second=0
    half=n//2
    for t in range(1,n):
        # limit to steps where data exists
        # generate signals every 10 steps only
        if t % 10 == 0:
            # momentum signals
            for a in assets:
                mids = H[a]['mid']
                # need past
                if t < HORIZ or not (np.isfinite(mids[t]) and np.isfinite(mids[t-HORIZ])):
                    continue
                past = mids[t] - mids[t-HORIZ]
                ph = holds_mem.get(a,0)
                pt = pos_mem.get(a,0.0)
                if ph>0:
                    holds_mem[a]=ph-1
                    target[a]=pt
                else:
                    if abs(past) < THR:
                        target[a]=0.0
                        pos_mem[a]=0.0
                    else:
                        sig = 1.0 if past>0 else -1.0
                        target[a]=sig
                        pos_mem[a]=sig
                        holds_mem[a]=HOLD
            # IDX diff if requested
            if thr_diff is not None:
                mA=H['A']['mid'][t]; mB=H['B']['mid'][t]; mC=H['C']['mid'][t]; mIDX=H['IDX']['mid'][t]
                if np.isfinite(mA) and np.isfinite(mB) and np.isfinite(mC) and np.isfinite(mIDX):
                    synth=0.3333*mA+0.6667*mB+0.1667*mC
                    diff=mIDX-synth
                    ph=holds_mem.get('IDX',0)
                    pt=pos_mem.get('IDX',0.0)
                    if ph>0:
                        holds_mem['IDX']=ph-1
                        target['IDX']=pt
                    else:
                        if abs(diff) < thr_diff:
                            target['IDX']=0.0
                            pos_mem['IDX']=0.0
                        else:
                            sig=-1.0 if diff>0 else 1.0
                            target['IDX']=sig*size_idx
                            pos_mem['IDX']=sig*size_idx
                            holds_mem['IDX']=hold_diff
                else:
                    # keep previous
                    pass
        # now move pos toward target (lots = target*15)
        for a in pos:
            tgt_lots = target[a]*15.0
            diff_lots = tgt_lots - pos[a]
            # limit 2 lots per step
            trade = np.clip(diff_lots, -2, 2)
            if abs(trade) > 1e-9:
                # cost: spread/2 + fee
                spread = H[a]['spread'][t]
                mid = H[a]['mid'][t]
                if not np.isfinite(spread):
                    spread = 9.0
                if not np.isfinite(mid):
                    continue
                cost_per_lot = spread/2.0 + fee_bps[a]*0.0001*mid  # bps = 1/10000
                # pnl from trade: we pay cost, and position will earn future price change
                # we account cost immediately
                c = abs(trade)*cost_per_lot
                pnl -= c
                if t < half:
                    pnl_first -= c
                else:
                    pnl_second -= c
                pos[a] += trade
            # mark to market pnl from price change * pos
            if t>0 and np.isfinite(H[a]['mid'][t]) and np.isfinite(H[a]['mid'][t-1]):
                delta = H[a]['mid'][t] - H[a]['mid'][t-1]
                mark = pos[a]*delta
                pnl += mark
                if t < half:
                    pnl_first += mark
                else:
                    pnl_second += mark
    return pnl, pnl_first, pnl_second

