    hold={a:0 for a in pos}
    target={a:0.0 for a in pos}
    holds_mem={}
    pos_mem={}
    pnl_hold=0
    fee_bps={'A':0,'A.X':3,'B':0,'B.X':3,'C':0,'C.X':3,'IDX':0}
