                    diff=mIDX-synth
                    ph=holds_mem.get('IDX',0)
                    pt=pos_mem.get('IDX',0.0)
                    if ph>0:
                        holds_mem['IDX']=ph-1
                        target['IDX']=pt
                    else:
                        if abs(diff) < thr_diff:
                            target['IDX']=0.0
                            pos_mem['IDX']=0.0
                        else:
                            sig=-1.0 if diff>0 else 1.0
                            target['IDX']=sig*0.6
                            pos_mem['IDX']=sig*0.6
                            holds_mem['IDX']=3
        for a in pos:
            tgt_lots=target[a]*15.0
            trade=np.clip(tgt_lots-pos[a],-2,2)
            if abs(trade)>1e-9:
                spread=H[a]['spread'][t]
                mid=H[a]['mid'][t]
                if not np.isfinite(spread): spread=9.0
                if not np.isfinite(mid): continue
                cost_per_lot=spread/2.0 + fee_bps[a]*0.0001*mid
                c=abs(trade)*cost_per_lot
                if t>=hold_start:
