def corr(a,b):
    m=np.isfinite(a)&np.isfinite(b)
    a=a[m]; b=b[m]
    if len(a)<100 or np.std(a)==0 or np.std(b)==0: return float('nan')
    return float(np.corrcoef(a,b)[0,1])

# Estimate net edge for momentum horizon H
# Assume we enter when |past| > thr, hold for HOLD steps, exit. Pay spread once entry+exit = avg_spread
# Expected profit ~ corr * vol_fwd * (past/vol_past) - spread_cost
# Let's compute empirical average profit for threshold strategies using mid prices
def estimate(asset, horiz, hold, thr):
    mid=H[asset]['mid']
    spread=H[asset]['spread']
    avg_spread=float(np.nanmean(spread))
    n=len(mid)
    profits=[]
    # scan t where signal triggered
    for t in range(horiz, n-hold-1):
        if not np.isfinite(mid[t]) or not np.isfinite(mid[t-horiz]):
            continue
        past=mid[t]-mid[t-horiz]
        if abs(past)<thr:
            continue
        sig=1 if past>0 else -1
        # future return over hold period
        if not np.isfinite(mid[t+hold]):
            continue
        fwd=mid[t+hold]-mid[t]
        # gross pnl per lot (cents) if long sig
        gross=sig*fwd
        net=gross - avg_spread # entry+exit approx one spread (conservative: half spread each side? but market order pays full spread? Let's use spread)
        # Actually to enter long you pay ask, exit pay bid => cost = spread. Use avg_spread
        profits.append(net)
    if len(profits)==0:
        return float('nan'),0,float('nan')
    arr=np.array(profits)
    winrate=float(np.mean(arr>0))
    avg=float(np.nanmean(arr))
    # also sharpe-like
    return avg, len(profits), winrate

