        if np.isfinite(H_cx[i+1]) and np.isfinite(H_cx[i]):
            pnl+= weights.get('cx',1)*pos_cx[i]*(H_cx[i+1]-H_cx[i])
        if np.isfinite(H_bx[i+1]) and np.isfinite(H_bx[i]):
            pnl+= weights.get('bx',1)*pos_bx[i]*(H_bx[i+1]-H_bx[i])
        if np.isfinite(H_idx[i+1]) and np.isfinite(H_idx[i]):
            pnl+= weights.get('hedge',1)*(pos_idx[i]*(H_idx[i+1]-H_idx[i]) + pa[i]*(H_a[i+1]-H_a[i]) + pb[i]*(H_b[i+1]-H_b[i]) + pc[i]*(H_c[i+1]-H_c[i]))
        pnl_series[i]=pnl
    # ignore nan
    pnl_series_clean = pnl_series[np.isfinite(pnl_series)]
    pnl = float(np.sum(pnl_series_clean))
    mean=float(np.mean(pnl_series_clean))
    std=float(np.std(pnl_series_clean))
    sh= mean/std*math.sqrt(1500) if std>0 else 0
    return pnl, sh, float(np.max(np.cumsum(pnl_series_clean)-np.maximum.accumulate(np.cumsum(pnl_series_clean)))) # drawdown approx

