def simulate_prem(thr, hold, scale=0.6):
    basket = 0.3333*H_a + 0.6667*H_b + 0.1667*H_c
    prem = H_idx - basket
    pos_idx = np.zeros(n)
    pos_a = np.zeros(n); pos_b=np.zeros(n); pos_c=np.zeros(n)
    hold_cnt=0
    cur=0
    for i in range(n):
        if hold_cnt>0:
            hold_cnt-=1
        else:
            if np.isfinite(prem[i]):
                if prem[i]>thr:
                    cur=-scale
                    hold_cnt=hold-1
                elif prem[i]<-thr:
                    cur=scale
                    hold_cnt=hold-1
                else:
                    cur=0
            else:
                cur=0
        pos_idx[i]=cur
        pos_a[i]= -cur*0.3333
        pos_b[i]= -cur*0.6667
        pos_c[i]= -cur*0.1667
    # pnl: sum pos * next return (mid change)
    pnl=0.0
    for i in range(n-1):
        if np.isfinite(H_idx[i+1]) and np.isfinite(H_idx[i]) and np.isfinite(H_a[i+1]) and np.isfinite(H_a[i]) and np.isfinite(H_b[i+1]) and np.isfinite(H_b[i]) and np.isfinite(H_c[i+1]) and np.isfinite(H_c[i]):
            d_idx = H_idx[i+1]-H_idx[i]
            d_a = H_a[i+1]-H_a[i]
            d_b = H_b[i+1]-H_b[i]
            d_c = H_c[i+1]-H_c[i]
            pnl += pos_idx[i]*d_idx + pos_a[i]*d_a + pos_b[i]*d_b + pos_c[i]*d_c
    # Sharpe approx via daily?
    # compute per-step pnl series
    pnl_series=np.zeros(n-1)
    for i in range(n-1):
        if np.isfinite(H_idx[i+1]) and np.isfinite(H_idx[i]):
            d_idx = H_idx[i+1]-H_idx[i]
            d_a = H_a[i+1]-H_a[i] if np.isfinite(H_a[i+1]) and np.isfinite(H_a[i]) else 0
            d_b = H_b[i+1]-H_b[i] if np.isfinite(H_b[i+1]) and np.isfinite(H_b[i]) else 0
            d_c = H_c[i+1]-H_c[i] if np.isfinite(H_c[i+1]) and np.isfinite(H_c[i]) else 0
            pnl_series[i]= pos_idx[i]*d_idx + pos_a[i]*d_a + pos_b[i]*d_b + pos_c[i]*d_c
    # Sharpe per epoch approx
    mean = np.nanmean(pnl_series)
    std = np.nanstd(pnl_series)
    sharpe = mean/std*math.sqrt(1500) if std>0 else 0
    return float(pnl), float(sharpe)

