def simulate_epoch(hold, sz_ax, sz_cx, sz_bx, thr_ax, thr_cx, thr_bx, hold_hedge, thr_hedge):
    # returns list of pnl per 1500 steps
    # generate positions as before
    def gen_mom(mid, thr, hold, sz):
        pos=np.zeros(n)
        hc=0; cur=0
        for i in range(n):
            if hc>0:
                hc-=1
                pos[i]=cur
            else:
                if i>=10 and np.isfinite(mid[i]) and np.isfinite(mid[i-10]):
                    past=mid[i]-mid[i-10]
                    if abs(past)<thr:
                        cur=0; pos[i]=0
                    else:
                        cur= sz if past>0 else -sz
                        hc=hold-1
                        pos[i]=cur
                else:
                    cur=0; pos[i]=0
        return pos
    pos_ax=gen_mom(H_ax, thr_ax, hold, sz_ax)
    pos_cx=gen_mom(H_cx, thr_cx, hold, sz_cx)
    pos_bx=gen_mom(H_bx, thr_bx, hold, sz_bx)
    basket=0.3333*H_a+0.6667*H_b+0.1667*H_c
    prem=H_idx-basket
    pos_idx=np.zeros(n); pa=np.zeros(n); pb=np.zeros(n); pc=np.zeros(n)
    hc=0; cur=0
    for i in range(n):
        if hc>0:
            hc-=1
        else:
            if np.isfinite(prem[i]):
                if prem[i]>thr_hedge:
                    cur=-0.6; hc=hold_hedge-1
                elif prem[i]<-thr_hedge:
                    cur=0.6; hc=hold_hedge-1
                else:
                    cur=0
            else:
                cur=0
        pos_idx[i]=cur; pa[i]=-cur*0.3333; pb[i]=-cur*0.6667; pc[i]=-cur*0.1667
    pnl_series=np.zeros(n-1)
    for i in range(n-1):
        pnl=0.0
        if np.isfinite(H_ax[i+1]) and np.isfinite(H_ax[i]): pnl+=pos_ax[i]*(H_ax[i+1]-H_ax[i])
        if np.isfinite(H_cx[i+1]) and np.isfinite(H_cx[i]): pnl+=pos_cx[i]*(H_cx[i+1]-H_cx[i])
        if np.isfinite(H_bx[i+1]) and np.isfinite(H_bx[i]): pnl+=pos_bx[i]*(H_bx[i+1]-H_bx[i])
        if np.isfinite(H_idx[i+1]) and np.isfinite(H_idx[i]):
            d_idx=H_idx[i+1]-H_idx[i]
            d_a=H_a[i+1]-H_a[i] if np.isfinite(H_a[i+1]) and np.isfinite(H_a[i]) else 0
            d_b=H_b[i+1]-H_b[i] if np.isfinite(H_b[i+1]) and np.isfinite(H_b[i]) else 0
            d_c=H_c[i+1]-H_c[i] if np.isfinite(H_c[i+1]) and np.isfinite(H_c[i]) else 0
            pnl+=pos_idx[i]*d_idx + pa[i]*d_a + pb[i]*d_b + pc[i]*d_c
        pnl_series[i]=pnl
    # per epoch 1500
    res=[]
    for start in range(0,n,1500):
        end=min(start+1500, n-1)
        res.append(float(np.sum(pnl_series[start:end])))
    return res

