def premium_pnl_slice(thr, hold, start, end):
    mA=H['A']['mid'][start:end]
    mB=H['B']['mid'][start:end]
    mC=H['C']['mid'][start:end]
    mIDX=H['IDX']['mid'][start:end]
    basket=0.3333*mA+0.6667*mB+0.1667*mC
    prem=mIDX-basket
    pos=0
    h=0
    positions=np.zeros_like(prem)
    for t in range(len(prem)):
        if h>0:
            h-=1
        else:
            if np.isfinite(prem[t]):
                if prem[t]>thr:
                    pos=-0.6
                    h=hold
                elif prem[t]<-thr:
