def run_bt_slice(start_frac, end_frac, thrA=10, thrB=6, thrC=12, hold=35, szA=0.6, szC=0.5, szB=0.5, prem_thr=28):
    n=len(H['A']['mid'])
    s0=int(n*start_frac); s1=int(n*end_frac)
    # simulate naive backtest slicing H
    # we need to simulate step by step with holdings
    # simplified pnl using mid price changes minus spread costs when trading
    # Let's approximate: we trade toward target with 2 lots per step max, but our targets hold for hold steps => trading only when signal flips
    # Use mid as execution proxy plus half spread + fee paid on traded lots
    # For simplicity we simulate signal generation using mid history window 20, hold logic, then compute pnl as position * price change - costs
    # Use 0.6 corresponds to 9 lots
    assets_signal=['A.X','B.X','C.X']
    thrs={'A.X':thrA,'B.X':thrB,'C.X':thrC}
    sizes={'A.X':szA,'B.X':szB,'C.X':szC}
    # map trade venue: for conservative we trade on X itself
    # but we also want variant that trades on primary using same signal; we'll test both later
    # Let's just compute pnl for X venues themselves using their mids and spreads
    import math
    state_h={}
    state_p={}
    pos={}
    for a in ['A.X','B.X','C.X','IDX','A','B','C']:
        pos[a]=0.0
    # state for IDX
    ih=0; ip=0.0
    pnl=0.0
    # half spreads approx from overview: A.X 4.95, B.X 3.16, C.X 5.5, IDX 5.47, A 5.74, B 3.98, C 6.27
    half_spread={'A.X':4.95,'B.X':3.16,'C.X':5.5,'IDX':5.47,'A':5.74,'B':3.98,'C':6.27}
    fee_bps={'A.X':0.0003,'B.X':0.0003,'C.X':0.0003,'A':0,'B':0,'C':0,'IDX':0}
    # price maps
    mids={}
    for a in pos.keys():
        mids[a]=H[a]['mid']
    # also need spreads per step? use avg for simplicity
    for t in range(s0+20, s1):
        targets={}
        # momentum
        for sig_asset in ['A.X','C.X','B.X']:
            thr=thrs[sig_asset]; sz=sizes[sig_asset]
            # mids window
            # get past
            m=mids[sig_asset]
            if not np.isfinite(m[t]) or not np.isfinite(m[t-12]):
                if state_h.get(sig_asset,0)>0:
                    state_h[sig_asset]-=1
                    targets[sig_asset]=state_p.get(sig_asset,0)
                else:
                    targets[sig_asset]=0.0
                    state_p[sig_asset]=0.0
                continue
            past=float(m[t]-m[t-12])
            h=state_h.get(sig_asset,0)
            if h>0:
                state_h[sig_asset]=h-1
                targets[sig_asset]=float(state_p.get(sig_asset,0))
                continue
            if abs(past)<thr:
                targets[sig_asset]=0.0
                state_p[sig_asset]=0.0
            else:
                sig=1 if past>0 else -1
                targets[sig_asset]=sig*sz
                state_p[sig_asset]=sig*sz
                state_h[sig_asset]=hold
        # IDX premium
        mA=mids['A'][t] if np.isfinite(mids['A'][t]) else mids['A.X'][t]
        mB=mids['B'][t] if np.isfinite(mids['B'][t]) else mids['B.X'][t]
        mC=mids['C'][t] if np.isfinite(mids['C'][t]) else mids['C.X'][t]
        mIDX=mids['IDX'][t]
        if ih>0:
            ih-=1
            if ip!=0:
                targets['IDX']=float(ip)
                hedge=-float(ip)
                targets['A']=hedge*0.33
                targets['B']=hedge*0.66
                targets['C']=hedge*0.17
            else:
                targets['IDX']=0.0
                targets['A']=0.0; targets['B']=0.0; targets['C']=0.0
        else:
            if np.isfinite(mA) and np.isfinite(mB) and np.isfinite(mC) and np.isfinite(mIDX):
                basket=0.3333*mA+0.6667*mB+0.1667*mC
                prem=float(mIDX-basket)
                if prem>prem_thr:
                    ip=-0.5; ih=hold
                    targets['IDX']=-0.5
                    targets['A']=0.165; targets['B']=0.33; targets['C']=0.085
                elif prem<-prem_thr:
                    ip=0.5; ih=hold
                    targets['IDX']=0.5
                    targets['A']=-0.165; targets['B']=-0.33; targets['C']=-0.085
                else:
                    ip=0.0
                    targets['IDX']=0.0
                    targets['A']=0.0; targets['B']=0.0; targets['C']=0.0
            else:
                targets['IDX']=0.0
                ip=0.0
        # fill missing
        for a in pos:
            if a not in targets:
                targets[a]=0.0
        # positions move towards targets at max delta 2 lots per asset per step? But our size 0.6 = 9 lots; need ~5 steps to reach.
        # Simulate execution toward target: position update limited to 2 per step
        for a in pos:
            tgt_lots = targets[a]*15
            delta = tgt_lots - pos[a]
            # limit 2 per 10 steps? Actually signal called every 10 steps but engine trades every step up to 2. So approx can move 2 per step => within hold period will reach.
            # Simplify: move at most 2 per step
            if delta>2: delta=2
            elif delta<-2: delta=-2
            if delta!=0:
                # cost: half spread + fee * price
                price=mids[a][t]
                if not np.isfinite(price):
                    continue
                cost = half_spread[a] + fee_bps[a]*price
                pnl -= abs(delta)*cost
                pos[a]+=delta
        # pnl from price change to next step
        if t+1 < s1:
            for a in pos:
                if pos[a]!=0 and np.isfinite(mids[a][t+1]) and np.isfinite(mids[a][t]):
                    pnl += pos[a]*(mids[a][t+1]-mids[a][t])
    result={'pnl':float(pnl)}
    return result

