                # but for non-primary, if IDX hedge inactive, A,B,C should be 0 unless hedge active; we already set
            last_targets=new_targets
        # trading step: move pos toward last_targets max 2 lots
        for a in pos:
            tgt=last_targets.get(a,0.0)*15
            delta=tgt-pos[a]
            if delta>2: delta=2
            elif delta<-2: delta=-2
            if delta!=0:
                price=H[a]['mid'][t]
                if not np.isfinite(price):
                    continue
                cost = half_spread[a] + fee[a]*price
                pnl -= abs(delta)*cost
                # attribute to period
                per=get_period(t)
                if per:
                    period_pnl[per] -= abs(delta)*cost
                pos[a]+=delta
        if t+1 < n:
            for a in pos:
                if pos[a]!=0 and np.isfinite(H[a]['mid'][t+1]) and np.isfinite(H[a]['mid'][t]):
                    chg = pos[a]*(H[a]['mid'][t+1]-H[a]['mid'][t])
                    pnl += chg
                    per=get_period(t)
                    if per:
                        period_pnl[per]+= chg
    return pnl, period_pnl

